hooks.command:
python3 -c "
import json, sys, os, hashlib, glob
try:
    # Session ID: TTY hash or PPID (no /proc walking)
    env_id = os.environ.get('CLAUDE_SESSION_ID', '')
    if env_id:
        key = env_id
    else:
        try:
            key = hashlib.md5(os.ttyname(0).encode()).hexdigest()[:8]
        except Exception:
            key = str(os.getppid())
    sf = f'/tmp/claude_task_session_{key}'
    session = None
    try:
        session = open(sf).read().strip() or None
    except (FileNotFoundError, OSError):
        pass
    # Read backlog safely
    try:
        with open('assets/backlog.json') as f:
            items = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        items = []
    in_progress = [i for i in items if i.get('status') == 'in_progress']
    mine = [i for i in in_progress if session and i.get('session') == session]
    others = [i for i in in_progress if session and i.get('session') != session]
    parts = []
    if mine:
        parts.append('MY ACTIVE TASK: ' + ', '.join(i['name'] for i in mine) + '. Run /task done when finished.')
    if others:
        parts.append('Other panels: ' + ', '.join(i['name'] + '(' + i.get('session','?') + ')' for i in others))
    if not mine and not others:
        parts.append('No active task. If doing meaningful work, run /task start first.')
    msg = 'TASK REMINDER: ' + ' '.join(parts)
    if session:
        msg += f' [session={session}]'
    json.dump({'hookSpecificOutput': {'hookEventName': 'UserPromptSubmit', 'additionalContext': msg}}, sys.stdout)
except Exception as e:
    # Fail silently with valid empty output so hook doesn't crash the session
    json.dump({'hookSpecificOutput': {'hookEventName': 'UserPromptSubmit', 'additionalContext': ''}}, sys.stdout)
"
